param([ValidateSet('build')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-out-matrix-shadow-20260914';$seed='D:\projects\AIMA-public-matrix-scope-20260914';$source='02f02eb1b4632d8cb2afd36a4987c1a0c8e5c1f9';$bundle='D:\projects\out-matrix-shadow-02f02eb.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'f5ff686fe17b17d4a8751ae19d0b12ec77ec1fe9d42d458f22d41bb7fd33f0b9'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $source;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $source -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\out-matrix-shadow-safety';$exe=Join-Path $build 'qrt-projection-safety.exe';$provider=Join-Path $repo 'build\out-matrix-shadow-provider'
$out=Join-Path $repo ('build\out-matrix-shadow-'+$Action+'-r1');$specPath=Join-Path $repo ('build\out-matrix-shadow-'+$Action+'-r1.json')
foreach($p in @($out,$specPath)){if(Test-Path $p){throw 'Evidence exists'}}
$null=New-Item -ItemType Directory -Path (Join-Path $repo 'build') -Force
$sourceFiles=@('native\providers\whole_provider.cpp','native\providers\q8192_matrix_producer_policy.h','native\providers\q8192_out_matrix_shadow_audit.h','tests\native\projection_safety_selftest.cpp','scripts\baiying_build_whole_provider.ps1')
foreach($dir in @('native\providers\moe_accumulator','native\providers\gdn','native\providers\ck_fmha','tests\native')){
 $sourceFiles+=@(Get-ChildItem (Join-Path $repo $dir) -Filter '*.h' -File|ForEach-Object {$_.FullName.Substring($repo.Length+1)})
}
$sourceInputs=@();foreach($file in ($sourceFiles|Sort-Object -Unique)){$sourceInputs+=@{file=$file;sha256=(Get-FileHash (Join-Path $repo $file) -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$source;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; native compile';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;replay_lanes=4;purpose='Build opt-in shadow comparison for both q8192 OUT families. The GB10-valid QKV4/OUT0 control drives inference; algorithm4 and original correction write independent guarded scratch. Compare every endpoint, classify up to4096 differences with original integer wave16 and cross-check the first on CPU. Preserve all admission bounds. Diagnostic timings are not performance acceptance.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$env:QRT_QWEN36_PROFILE_MATRIX_PRODUCER_WALL='0';$env:QRT_QWEN36_PREFILL_HIPBLASLT_PRODUCER='1';$env:QRT_QWEN36_Q8192_MATRIX_PRODUCER_ALGORITHM='0';$env:QRT_QWEN36_Q8192_MATRIX_PRODUCER_SCOPE='all'
$env:QRT_QWEN36_HAWKEYE_DEVICE_REPLAY='0';$env:QRT_QWEN36_HAWKEYE_PREPARED_OPERANDS='1';$env:QRT_QWEN36_HAWKEYE_PREVALIDATED_FLOAT_REPLAY='1';$env:QRT_QWEN36_HAWKEYE_PARTITION_REPLAY='0';$env:QRT_QWEN36_HAWKEYE_ABSOLUTE_PRODUCT_BOUND='0';$env:QRT_QWEN36_HAWKEYE_PREPARED_K16_MAJOR='0';$env:QRT_QWEN36_HAWKEYE_FLOAT_REPLAY='0';$env:QRT_QWEN36_HAWKEYE_ABSOLUTE_PRODUCT_AUDIT='0';$env:QRT_QWEN36_HAWKEYE_ABSOLUTE_PRODUCT_HIPBLASLT='0';$env:QRT_QWEN36_HAWKEYE_PACKED_CANDIDATES='0';$env:QRT_QWEN36_HAWKEYE_CORRECTION_MAXIMUM_BLOCKS_PER_LAUNCH='4096'
foreach($name in @('SCALAR','TILED','BOUNDED','SCALED','ROW_MAX','F32_CARRY','RANGE','PARTITION','INTERVAL')){[Environment]::SetEnvironmentVariable('QRT_PROJECTION_SAFETY_'+$name+'_REPLAY','0','Process')}
$spec.matrix_producer_algorithm=[int]$env:QRT_QWEN36_Q8192_MATRIX_PRODUCER_ALGORITHM

if(Test-Path $provider){throw 'Build exists'}
$spec.executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
$spec.arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_whole_provider.ps1'),'-OutDir',$provider,'-DppReduction','1','-CompactNormalize','1','-HawkeyeReplayLanes','4','-CompileTimeoutSeconds','240')
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds 270|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native scoped producer build failed'}
